function installationPriorProbe(EntryEnvironment $x,array $prior,bool $expected,?SoSecurity\Account\StateCredentialEnrollment $fresh=null):void
{
    $profile=$x->e->factors->statePolicy('managed-test','tenant',str_repeat('e',64),$x->e->keys);$ref=$x->e->factors->stateReference($prior['scope'],$prior['subject'],$profile['context']);
    foreach($fresh===null?[false,true]:[false] as $recovery){$dir=privateDirectory();try{
        mkdir($dir.'/factors',0700);mkdir($dir.'/fence',0700);copy($x->e->directory.'/factors/'.$ref['file'],$dir.'/factors/'.$ref['file']);chmod($dir.'/factors/'.$ref['file'],0600);
        $fence=new SoSecurity\Account\LocalEpochFence($dir.'/fence','managed-test','tenant',str_repeat('e',64),$x->e->keys,static function($h)use($dir):bool{return witnessPersist($h,$dir.'/fence');});$fence->initialize();$clock=new TestClock();$clock->time=$x->e->clock->time+30;
        $raw=new SoSecurity\Mfa\TotpFactors(new SoSecurity\Storage\FileStore($dir.'/factors','managed-factor-test',$clock),new SoSecurity\Crypto\Cipher('test',['test'=>str_repeat('t',32)],'managed-test'),'Managed test',$clock);$factors=$raw->managed('managed-test','tenant',str_repeat('e',64),$x->e->keys,$fence,static function():bool{return true;});
        $secret=$x->e->secret;if($fresh!==null){parse_str(parse_url($fresh->enrollment()->provisioningUri(),PHP_URL_QUERY),$params);$secret=$params['secret'];}$proof=$recovery?$x->e->codes[0]:(new SoSecurity\Mfa\Totp())->codeAt($secret,$clock->time);Check::same($expected,$factors->verifyBound($prior['scope'],$prior['subject'],$prior['factor_id'],$proof,$recovery));
    }finally{cleanDirectory($dir.'/factors');cleanDirectory($dir.'/fence');rmdir($dir);}}
}
