    file_put_contents($path,$oldRaw.' ');witnessReason('account.installation_changed',static function()use($next,$review,$plan,$control,$token,$grant):void{$next->installCredentials($review,$plan,$control,'user',$token,$grant,'witnessBudget');});Check::same($before,$next->inspect('witnessBudget'));file_put_contents($path,$oldRaw);
